# Host/port only from database configs (no passwords)
function ShowDbHost($path) {
  if (-not (Test-Path $path)) { Write-Host "MISSING: $path"; return }
  Write-Host "=== $path ==="
  Get-Content $path | Where-Object { $_ -match '(?i)host|port|database|jdbc|mysql|enabled|use-shared|shared' -and $_ -notmatch '(?i)password|pass|user|username|token|secret|key' }
}
ShowDbHost "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\RootMC\database.yml"
ShowDbHost "D:\.1 Work Stations\RootMC\Server Handoffs\2. RootMC - Towny\plugins\RootMC\database.yml"
# Skills configs in handoffs
Get-ChildItem -Path "D:\.1 Work Stations\RootMC\Server Handoffs" -Recurse -Filter "*skills*" -ErrorAction SilentlyContinue | Select-Object FullName, Length
Get-ChildItem -Path "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins" -Directory | Select-Object Name
# Check for Root-Skills data folder
@("D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\Root-Skills", "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\root-skills") | ForEach-Object { Write-Host "exists $_ : $(Test-Path $_)" }

# Tiny/suspect jars in Claims handoff (< 50KB or unusual)
Get-ChildItem "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\*.jar" | Where-Object { $_.Length -lt 100000 } | Select-Object Name, Length
# Validate zip END headers for all Claims jars
$bad=@(); $ok=@()
Get-ChildItem "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\*.jar" | ForEach-Object {
  try {
    $fs=[IO.File]::OpenRead($_.FullName)
    $br=New-Object IO.BinaryReader($fs)
    $fs.Seek(-22, 'End') | Out-Null
    $sig=$br.ReadUInt32()
    $br.Close(); $fs.Close()
    if ($sig -ne 0x06054b50) { $bad += "$($_.Name) bad_sig=0x$($sig.ToString('X8')) size=$($_.Length)" }
    else { $ok += $_.Name }
  } catch { $bad += "$($_.Name) ERROR: $_" }
}
Write-Host "OK count: $($ok.Count)"; Write-Host "BAD:"; $bad
# Compare build outputs
$buildLibs = @(
  "D:\.1 Work Stations\RootMC\Plugin Building\Minecraft\plugins\root-core\build\libs",
  "D:\.1 Work Stations\RootMC\Plugin Building\Minecraft\plugins\root-perms\build\libs",
  "D:\.1 Work Stations\RootMC\Plugin Building\Minecraft\plugins\root-skills\build\libs"
)
foreach ($d in $buildLibs) {
  Write-Host "=== $d ==="
  if (Test-Path $d) { Get-ChildItem $d -Filter "*.jar" | Select-Object Name, Length, LastWriteTime | Format-Table -AutoSize } else { Write-Host "missing" }
}

# Validate zip END headers for Claims jars
$bad=@(); $ok=0
Get-ChildItem "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\*.jar" | ForEach-Object {
  try {
    $fs=[IO.File]::OpenRead($_.FullName)
    $br=New-Object IO.BinaryReader($fs)
    $fs.Seek(-22, 'End') | Out-Null
    $sig=$br.ReadUInt32()
    $br.Close(); $fs.Close()
    if ($sig -ne 0x06054b50) { $bad += "$($_.Name) bad_sig=0x$($sig.ToString('X8')) size=$($_.Length)" }
    else { $ok++ }
  } catch { $bad += "$($_.Name) ERROR: $_" }
}
Write-Host "OK: $ok  BAD count: $($bad.Count)"
$bad | ForEach-Object { Write-Host $_ }
Write-Host "--- tiny (<100k) ---"
Get-ChildItem "D:\.1 Work Stations\RootMC\Server Handoffs\1. RootMC - Claims\plugins\*.jar" | Where-Object { $_.Length -lt 100000 } | Select-Object Name, Length | Format-Table -AutoSize
Write-Host "--- build libs ---"
foreach ($mod in @("root-core","root-perms","root-skills","root-discord")) {
  $d="D:\.1 Work Stations\RootMC\Plugin Building\Minecraft\plugins\$mod\build\libs"
  Write-Host "=== $mod ==="
  if (Test-Path $d) { Get-ChildItem $d -Filter "*.jar" | ForEach-Object { "$($_.Name) $($_.Length) $($_.LastWriteTime)" } } else { "missing $d" }
}
